@Composable fun WorkEventRow(type:EventType,timestamp:Long?,onClick:()->Unit={}){val s=when(type){EventType.WORK_START->Triple(Icons.Default.PlayArrow,"Munkakezdés",Green);EventType.TRIP_START->Triple(Icons.Default.DirectionsCar,"Útra indulás",Blue);EventType.TRIP_END->Triple(Icons.Default.Flag,"Visszaérkezés",Orange);EventType.WORK_END->Triple(Icons.Default.Stop,"Munka vége",DarkGray)};val tripIndent=if(type==EventType.TRIP_START||type==EventType.TRIP_END)18.dp else 5.dp;Row(Modifier.fillMaxWidth().height(55.dp).padding(start=tripIndent,end=5.dp),verticalAlignment=Alignment.CenterVertically){Surface(shape=CircleShape,color=s.third,modifier=Modifier.size(31.dp)){Icon(s.first,null,tint=Color.White,modifier=Modifier.padding(6.dp))};Spacer(Modifier.width(12.dp));Text(s.second,Modifier.weight(1f),fontWeight=FontWeight.Medium,fontSize=14.sp);timestamp?.let{Text(time(it),color=s.third,fontWeight=FontWeight.Bold,fontSize=13.sp);IconButton(onClick,Modifier.size(36.dp)){Icon(Icons.Default.Edit,"Időpont szerkesztése",tint=DarkGray,modifier=Modifier.size(18.dp))}}?:run{IconButton(onClick,Modifier.size(36.dp)){Icon(Icons.Default.Edit,"Időpont beállítása",tint=DarkGray,modifier=Modifier.size(18.dp))}}};HorizontalDivider(color=Border)}
