private data class RoadMatrix(val durations:Array<DoubleArray>,val distances:Array<DoubleArray>)
private data class RouteResult(val stops:List<LocationPlace>,val seconds:Double,val meters:Double,val roadBased:Boolean)
private suspend fun roadMatrix(points:List<LocationPlace>):RoadMatrix=withContext(Dispatchers.IO){
    require(points.size<=50){"Legfeljebb 48 napi megálló optimalizálható egyszerre."}
    val coords=points.joinToString(";"){"${it.longitude},${it.latitude}"};val connection=(URL("https://router.project-osrm.org/table/v1/driving/$coords?annotations=duration,distance").openConnection() as HttpURLConnection).apply{connectTimeout=15000;readTimeout=25000;setRequestProperty("User-Agent","RoadRecord-Android/1.13")}
    try{if(connection.responseCode !in 200..299)error("Az útvonal-szolgáltatás nem elérhető (${connection.responseCode}).");val root=JSONObject(connection.inputStream.bufferedReader().use{it.readText()});fun matrix(name:String):Array<DoubleArray>{val rows=root.getJSONArray(name);return Array(rows.length()){i->val row=rows.getJSONArray(i);DoubleArray(row.length()){j->if(row.isNull(j))Double.POSITIVE_INFINITY else row.getDouble(j)}}};RoadMatrix(matrix("durations"),matrix("distances"))}finally{connection.disconnect()}
}
private fun optimizeByTime(start:LocationPlace,end:LocationPlace?,stops:List<LocationPlace>,locked:Map<Long,Int>,matrix:RoadMatrix):RouteResult{
    val all=(listOf(start)+stops+listOfNotNull(end)).distinctBy{it.id};val idx=all.mapIndexed{i,p->p.id to i}.toMap();val result=MutableList<LocationPlace?>(stops.size){null};locked.forEach{(id,pos)->stops.firstOrNull{it.id==id}?.let{if(pos in result.indices&&result[pos]==null)result[pos]=it}}
    val free=stops.filter{p->result.none{it?.id==p.id}}.toMutableList();var previous=start
    result.indices.forEach{i->if(result[i]==null){val next=free.minByOrNull{matrix.durations[idx.getValue(previous.id)][idx.getValue(it.id)]}?:return@forEach;result[i]=next;free.remove(next);previous=next}else previous=result[i]!!}
    var route=result.filterNotNull().toMutableList();fun time(r:List<LocationPlace>):Double{val path=listOf(start)+r+listOfNotNull(end);return path.zipWithNext().sumOf{matrix.durations[idx.getValue(it.first.id)][idx.getValue(it.second.id)]}}
    var improved=true;while(improved){improved=false;var best=time(route);for(i in route.indices)for(j in i+1 until route.size){if(locked.containsKey(route[i].id)||locked.containsKey(route[j].id))continue;val candidate=route.toMutableList().also{Collections.swap(it,i,j)};val score=time(candidate);if(score+1<best){route=candidate;best=score;improved=true}}}
    val path=listOf(start)+route+listOfNotNull(end);return RouteResult(route,path.zipWithNext().sumOf{matrix.durations[idx.getValue(it.first.id)][idx.getValue(it.second.id)]},path.zipWithNext().sumOf{matrix.distances[idx.getValue(it.first.id)][idx.getValue(it.second.id)]},true)
}
private fun airFallback(start:LocationPlace,end:LocationPlace?,stops:List<LocationPlace>,locked:Map<Long,Int>):RouteResult{val result=MutableList<LocationPlace?>(stops.size){null};locked.forEach{(id,pos)->stops.firstOrNull{it.id==id}?.let{if(pos in result.indices)result[pos]=it}};val free=stops.filter{p->result.none{it?.id==p.id}}.toMutableList();var current=start;result.indices.forEach{i->if(result[i]==null){val next=free.minBy{routeDistance(current,it)};result[i]=next;free.remove(next);current=next}else current=result[i]!!};val route=result.filterNotNull();val path=listOf(start)+route+listOfNotNull(end);val km=path.zipWithNext().sumOf{sqrt(routeDistance(it.first,it.second))*111.0*1.25};return RouteResult(route,km/55.0*3600,km*1000,false)}
private fun routeDistance(a:LocationPlace,b:LocationPlace):Double{val lat1=a.latitude?:return Double.MAX_VALUE;val lat2=b.latitude?:return Double.MAX_VALUE;val lon1=a.longitude?:return Double.MAX_VALUE;val lon2=b.longitude?:return Double.MAX_VALUE;val x=(lon2-lon1)*cos(Math.toRadians((lat1+lat2)/2));val y=lat2-lat1;return x*x+y*y}
private fun openPlannedRoute(ctx:Context,start:LocationPlace,route:List<LocationPlace>){val origin="${start.latitude},${start.longitude}";val destination=route.lastOrNull()?.let{"${it.latitude},${it.longitude}"}?:origin;val waypoints=route.dropLast(1).joinToString("%7C"){"${it.latitude},${it.longitude}"};val url="https://www.google.com/maps/dir/?api=1&origin=$origin&destination=$destination&waypoints=$waypoints&travelmode=driving";ctx.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}
private fun movableTarget(order:List<LocationPlace>,place:LocationPlace,requested:Int,locked:Map<Long,Int>):Int{val current=order.indexOfFirst{it.id==place.id};if(current<0||locked.containsKey(place.id))return current;val fixed=locked.values.sorted();val lower=(fixed.lastOrNull{it<current}?:-1)+1;val upper=(fixed.firstOrNull{it>current}?:order.size)-1;return requested.coerceIn(lower,upper)}
@Composable private fun RouteMapPreview(home:LocationPlace,stops:List<LocationPlace>){
    val points=(listOf(home)+stops).filter{it.latitude!=null&&it.longitude!=null}
    RRCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){
        Text("Térképes útvonal",fontWeight=FontWeight.Bold,color=Navy);Spacer(Modifier.height(8.dp))
        Canvas(Modifier.fillMaxWidth().height(190.dp).background(Color(0xFFEAF2E8),RoundedCornerShape(9.dp)).padding(18.dp)){
            if(points.isNotEmpty()){
                val minLat=points.minOf{it.latitude!!};val maxLat=points.maxOf{it.latitude!!};val minLon=points.minOf{it.longitude!!};val maxLon=points.maxOf{it.longitude!!}
                val latRange=(maxLat-minLat).coerceAtLeast(.001);val lonRange=(maxLon-minLon).coerceAtLeast(.001)
                val position:(LocationPlace)->Offset={p->Offset(((p.longitude!!-minLon)/lonRange*size.width).toFloat(),(size.height-(p.latitude!!-minLat)/latRange*size.height).toFloat())}
                points.zipWithNext().forEach{pair->drawLine(Blue,position(pair.first),position(pair.second),5f,StrokeCap.Round)}
                points.dropLast(1).forEachIndexed{i,p->drawCircle(if(i==0)Green else Orange,if(i==0)12f else 9f,position(p))}
            }
        }
    }}
}
