    val places by vm.places.collectAsState();val plans by vm.repo.plans(dayId).collectAsState(initial=emptyList());val config by vm.repo.routeConfig(dayId).collectAsState(initial=null);val ctx=LocalContext.current;val scope=rememberCoroutineScope();val listState=rememberLazyListState()
