    fun rerouteFromGps(){LocationServices.getFusedLocationProviderClient(ctx).getCurrentLocation(com.google.android.gms.location.Priority.PRIORITY_HIGH_ACCURACY,null).addOnSuccessListener{l->if(l!=null)optimize(LocationPlace(id=Long.MIN_VALUE,name="Jelenlegi helyzet",latitude=l.latitude,longitude=l.longitude))else error="A jelenlegi GPS-helyzet nem olvasható."}.addOnFailureListener{error="A jelenlegi GPS-helyzet nem olvasható."}}
